-- Add archive fields to events table`nALTER TABLE public.events ADD COLUMN IF NOT EXISTS summary text;`nALTER TABLE public.events ADD COLUMN IF NOT EXISTS recording_url text;`n`n-- Create Resources table`nCREATE TABLE IF NOT EXISTS public.resources (`n    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,`n    title text NOT NULL,`n    description text,`n    link text NOT NULL,`n    category text NOT NULL, -- roadmaps, practice, dsa, placement, general`n    event_id uuid REFERENCES public.events(id) ON DELETE SET NULL,`n    is_active boolean DEFAULT true NOT NULL,`n    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL`n);`n`n-- Enable RLS`nALTER TABLE public.resources ENABLE ROW LEVEL SECURITY;`n`n-- Policies`nCREATE POLICY \"Public can view active resources\" ON public.resources FOR SELECT USING (is_active = true);`nCREATE POLICY \"Admins have full access to resources\" ON public.resources FOR ALL USING (public.is_admin_or_organizer());
